using System.Threading.Tasks;

[Form]
public class NDXDataTransferFromAX2009 extends FormRun
{
    NDXProdIdentProcedureFromAX2009 nDXProdIdentProcedureFromAX2009;
    NDXProdIdentBlockFromAX2009 nDXProdIdentBlockFromAX2009;
    NDXProdIdentPackagingFromAX2009 nDXProdIdentPackagingFromAX2009;
    NDXTokenizerExcludesFromAX2009 nDXTokenizerExcludesFromAX2009;
    NDXProdIdentLabelItemsFromAX2009 nDXProdIdentLabelItemsFromAX2009;
    NDXProdIdentLabelFromAX2009 nDXProdIdentLabelFromAX2009;
    TimeOfDay secStart, secStop;
    boolean taskIsNotRunningStatusSet;

}

/// <summary>
/// PaffH 27.07.22
/// </summary>
public void run()
{
    super();

    DetailPanel.setFocus();
    element.setTimeoutEx(formMethodStr(NDXDataTransferFromAX2009,timer01 ), conNull(), 1000);
}

public void timer01(AsyncTaskResult _result)
{
    boolean taskIsRunning = false;
    if (!element.closed())
    {
        System.Threading.Tasks.Task task;
        if (nDXProdIdentProcedureFromAX2009)
        {
            task = nDXProdIdentProcedureFromAX2009.parmTask1();
            if (task)
            {
                if (task.Status == System.Threading.Tasks.TaskStatus::Running && !secStart)
                {
                    secStart = NDXHelperCommon::timeNow();
                    taskIsNotRunningStatusSet = false;
                }

                if (task.Status != System.Threading.Tasks.TaskStatus::RanToCompletion)
                {
                    taskIsRunning = true;
                    FormStringReadFromQueueStatus.text(task.Status.ToString());
                    int runTime = NDXHelperCommon::timeNow() - secStart;

                    FormIntegerRuntimeSec.value(runTime);
                    FormStringRuntime.text(NDXHelperCommon::seconds2Str(runTime));
                }
            }
        }
        if (!taskIsRunning && !taskIsNotRunningStatusSet)
        {

            secStart = 0;
            FormStringReadFromQueueStatus.text("@NDX:NDXNotRunning");
            FormIntegerRuntimeSec.value(0);
            FormStringRuntime.text(NDXHelperCommon::seconds2Str(0));

            NDXProdIdentProcedureTable_1_ds.executeQuery();
            NDXProdIdentPackaging_3_ds.executeQuery();

            taskIsNotRunningStatusSet = true;
        }
        element.setTimeoutEx(formMethodStr(NDXDataTransferFromAX2009,timer01 ), conNull(), 1000);
    }
}

/// <summary>
/// PaffH 27.07.22
/// </summary>
public void init()
{
    super();
    secStart = 0;
    secStop = 0;
    taskIsNotRunningStatusSet = false;
    FormGridNDXProdIdentBlockTable_2.visibleRows(20);
    FormGridNDXProdIdentPackaging_3.visibleRows(20);
    FormGridNDXTokenizerExcludes_4.visibleRows(30);
}

